package io.knowledgebrain.space;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GroupReviewAuthorizationTest {
 GroupSpaceStore store=mock(GroupSpaceStore.class);IdentityPrincipalClient identity=mock(IdentityPrincipalClient.class);GroupReviewAuthorizationController api=new GroupReviewAuthorizationController(store,identity,"a".repeat(43));UuidV7 ids=new UuidV7(Clock.systemUTC());UUID group=ids.next(),principal=ids.next(),space=ids.next();String token="b".repeat(43);
 MockHttpServletRequest r(String body){var r=new MockHttpServletRequest("POST","/internal/space/group-review-authorization");r.setSecure(true);r.setContentType("application/json");r.addHeader("Authorization","Bearer "+"a".repeat(43));r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 String body(){return "{\"token\":\""+token+"\",\"groupId\":\""+group+"\"}";}
 @Test void registeredIdentityIsResolvedForEveryRequest()throws Exception{when(identity.resolve(token,null)).thenReturn(new IdentityPrincipalClient.Principal(principal,"GUEST",Instant.now().plusSeconds(60)));assertThrows(ResponseStatusException.class,()->api.check(r(body())));verifyNoInteractions(store);when(identity.resolve(token,null)).thenReturn(new IdentityPrincipalClient.Principal(principal,"REGISTERED",Instant.now().plusSeconds(60)));when(store.reviewAccess(group,principal)).thenReturn(new GroupSpaceStore.ReviewAccess(group,space,principal,7));assertEquals(7,api.check(r(body())).getBody().membershipVersion());verify(identity,times(2)).resolve(token,null);}
 @Test void dedicatedKeyTlsNoBrowserCookieAndStrictInputRequired(){for(String body:List.of("{}",body()+" {}",body().replace("}",",\"principalId\":null}"),body().replace("}",",\"token\":\""+token+"\"}")))assertThrows(ResponseStatusException.class,()->api.check(r(body)));var insecure=r(body());insecure.setSecure(false);assertThrows(ResponseStatusException.class,()->api.check(insecure));var wrong=r(body());wrong.removeHeader("Authorization");wrong.addHeader("Authorization","Bearer "+"c".repeat(43));assertThrows(ResponseStatusException.class,()->api.check(wrong));var browser=r(body());browser.addHeader("Cookie","__Host-brain_guest="+token);assertThrows(ResponseStatusException.class,()->api.check(browser));verifyNoInteractions(identity,store);}
}
